import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, NavLink } from 'react-router-dom';
import Dashboard from './pages/Dashboard';
import Volunteers from './pages/Volunteers';
import Shifts from './pages/Shifts';
import Ministries from './pages/Ministries';
import Availability from './pages/Availability';
import GenerateSchedule from './pages/GenerateSchedule';
import ConfirmSchedule from './pages/ConfirmSchedule';
import Reports from './pages/Reports';
import Settings from './pages/Settings';
import { ThemeProvider, useTheme } from './context/ThemeContext';

const menuItems = [
  { path: '#/', icon: '📊', label: 'Dashboard', exact: true },
  { path: '#/volunteers', icon: '👥', label: 'Voluntários' },
  { path: '#/ministries', icon: '⛪', label: 'Ministérios' },
  { path: '#/shifts', icon: '🕐', label: 'Turnos' },
  { path: '#/availability', icon: '📅', label: 'Disponibilidade' },
  { path: '#/generate', icon: '⚡', label: 'Gerar Escala' },
  { path: '#/confirm', icon: '✅', label: 'Confirmar' },
  { path: '#/reports', icon: '📈', label: 'Relatórios' },
  { path: '#/settings', icon: '⚙️', label: 'Configurações' },
];

function AppLayout({ children }) {
  const { theme } = useTheme();
  const [menuOpen, setMenuOpen] = useState(false);

  const navStyle = ({ isActive }) => ({
    display: 'flex', alignItems: 'center', gap: '12px', padding: '12px 16px',
    color: isActive ? 'white' : 'rgba(255,255,255,0.7)',
    backgroundColor: isActive ? theme.primary : 'transparent',
    textDecoration: 'none', borderRadius: '8px', marginBottom: '4px',
    fontWeight: isActive ? '600' : '400',
  });

  return (
    <div style={{ fontFamily: 'Segoe UI, sans-serif', backgroundColor: theme.background, minHeight: '100vh' }}>
      {/* Header */}
      <header style={{
        position: 'fixed', top: 0, left: 0, right: 0, height: '60px',
        backgroundColor: theme.surface, borderBottom: `1px solid ${theme.border}`,
        display: 'flex', alignItems: 'center', justifyContent: 'space-between',
        padding: '0 20px', zIndex: 100, boxShadow: '0 2px 8px rgba(0,0,0,0.08)',
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <button onClick={() => setMenuOpen(true)} style={{
            background: 'none', border: 'none', fontSize: '24px', cursor: 'pointer', padding: '8px'
          }}>☰</button>
          <div style={{
            width: '36px', height: '36px', borderRadius: '8px', backgroundColor: theme.primary,
            display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '18px'
          }}>⛪</div>
          <span style={{ fontSize: '18px', fontWeight: '700', color: theme.text }}>Kalendarz</span>
        </div>
        <div style={{ display: 'flex', gap: '8px' }}>
          <button style={{ background: 'none', border: 'none', fontSize: '20px', cursor: 'pointer' }}>🔔</button>
          <button style={{ background: 'none', border: 'none', fontSize: '20px', cursor: 'pointer' }}>👤</button>
        </div>
      </header>

      {/* Drawer Menu */}
      {menuOpen && (
        <>
          <div onClick={() => setMenuOpen(false)} style={{
            position: 'fixed', inset: 0, backgroundColor: 'rgba(0,0,0,0.5)', zIndex: 99
          }} />
          <nav style={{
            position: 'fixed', top: 0, left: 0, width: '260px', height: '100vh',
            backgroundColor: '#1E293B', zIndex: 100, padding: '20px', overflowY: 'auto'
          }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '20px' }}>
              <div style={{ width: '40px', height: '40px', borderRadius: '10px', backgroundColor: theme.primary, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '20px' }}>⛪</div>
              <span style={{ color: 'white', fontSize: '18px', fontWeight: '600' }}>Kalendarz</span>
            </div>
            {menuItems.map((item) => (
              <NavLink key={item.path} to={item.path} onClick={() => setMenuOpen(false)} style={navStyle}>
                <span>{item.icon}</span>
                <span>{item.label}</span>
              </NavLink>
            ))}
            <div style={{ marginTop: 'auto', paddingTop: '20px', borderTop: '1px solid rgba(255,255,255,0.1)' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '12px', color: 'rgba(255,255,255,0.7)', cursor: 'pointer' }}>
                <span>🚪</span>
                <span>Sair</span>
              </div>
            </div>
          </nav>
        </>
      )}

      {/* Main Content */}
      <main style={{ paddingTop: '80px', padding: '20px' }}>
        {children}
      </main>
    </div>
  );
}

function App() {
  useEffect(() => {
    if ('serviceWorker' in navigator) {
      window.addEventListener('load', () => {
        navigator.serviceWorker.register('/service-worker.js')
          .then(reg => console.log('SW registered:', reg))
          .catch(err => console.log('SW failed:', err));
      });
    }
  }, []);

  return (
    <ThemeProvider>
      <HashRouter>
        <AppLayout>
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/volunteers" element={<Volunteers />} />
            <Route path="/ministries" element={<Ministries />} />
            <Route path="/shifts" element={<Shifts />} />
            <Route path="/availability" element={<Availability />} />
            <Route path="/generate" element={<GenerateSchedule />} />
            <Route path="/confirm" element={<ConfirmSchedule />} />
            <Route path="/reports" element={<Reports />} />
            <Route path="/settings" element={<Settings />} />
          </Routes>
        </AppLayout>
      </HashRouter>
    </ThemeProvider>
  );
}

export default App;
